package in.gezeno.businesssuite;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.net.Uri;import android.provider.Settings;import android.view.*;import android.widget.*;import android.database.*;import java.io.*;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
 DB db; LinearLayout root,body; TextView title; String[] nav={"Dashboard","Customers","Vendors","Products","Purchases","Orders","Invoices","Payments","Stock","Reports","Catalogue","Settings"};
 int blue=Color.rgb(20,87,200),dark=Color.rgb(13,43,100),bg=Color.rgb(246,248,252); DateFormat df=new SimpleDateFormat("dd MMM yyyy",Locale.getDefault());
 @Override public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);showLogin();}
 TextView tv(String s,int sp){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(dark);t.setPadding(18,12,18,12);return t;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
 EditText ed(String hint){EditText e=new EditText(this);e.setHint(hint);e.setSingleLine(false);e.setPadding(16,12,16,12);return e;}
 LinearLayout box(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(14,8,14,8);return l;}
 void showLogin(){LinearLayout l=box();l.setGravity(Gravity.CENTER);l.setBackgroundColor(bg);TextView h=tv("GEZENO\nBusiness Suite",30);h.setTextColor(blue);h.setGravity(Gravity.CENTER);l.addView(h);EditText u=ed("Username");u.setText(db.get("username"));l.addView(u);EditText p=ed("Password");p.setInputType(0x81);p.setText("");l.addView(p);Button x=btn("LOGIN");l.addView(x);TextView hint=tv("Offline-first B2B management • Data stays on this device",14);hint.setGravity(Gravity.CENTER);l.addView(hint);x.setOnClickListener(v->{if(u.getText().toString().equals(db.get("username"))&&p.getText().toString().equals(db.get("password")))showApp();else Toast.makeText(this,"Invalid username or password",Toast.LENGTH_SHORT).show();});setContentView(l);}
 void showApp(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setBackgroundColor(blue);title=tv(db.get("brand")+" • Dashboard",21);title.setTextColor(Color.WHITE);head.addView(title,new LinearLayout.LayoutParams(0,72,1));Button settings=btn("SETTINGS");head.addView(settings,new LinearLayout.LayoutParams(-2,60));settings.setOnClickListener(v->page("Settings"));root.addView(head);ScrollView sv=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(12,12,12,100);sv.addView(body);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));HorizontalScrollView navsv=new HorizontalScrollView(this);LinearLayout nb=new LinearLayout(this);for(String n:nav){Button b=btn(n);nb.addView(b,new LinearLayout.LayoutParams(-2,60));b.setOnClickListener(v->page(((Button)v).getText().toString()));}navsv.addView(nb);root.addView(navsv,new LinearLayout.LayoutParams(-1,70));setContentView(root);page("Dashboard");}
 void page(String n){title.setText(db.get("brand")+" • "+n);body.removeAllViews();switch(n){case"Dashboard":dashboard();break;case"Customers":customers();break;case"Vendors":vendors();break;case"Products":products();break;case"Purchases":purchases();break;case"Orders":orders();break;case"Invoices":invoices();break;case"Payments":payments();break;case"Stock":stock();break;case"Reports":reports();break;case"Catalogue":catalogue();break;case"Settings":settings();}}
 void dashboard(){body.addView(tv("Welcome to "+db.get("brand")+" Business Suite",26));body.addView(tv("Today: "+df.format(new Date()),16));LinearLayout cards=new LinearLayout(this);cards.setOrientation(LinearLayout.VERTICAL);String[][] m={{"Customers",count("customers")},{"Products",count("products")},{"Orders",count("orders")},{"Stock Units",sum("products","stock")},{"Sales",money("orders","total")},{"Due",money("orders","due")}};for(String[] z:m){TextView c=tv(z[0]+"\n"+z[1],19);c.setBackgroundColor(Color.WHITE);cards.addView(c); }body.addView(cards);body.addView(tv("Quick Actions",23));for(String n:new String[]{"Add Customer","Add Product","Create Order","Create Purchase","Record Payment","Create Invoice","Reports"}){Button b=btn(n);body.addView(b);b.setOnClickListener(v->{String s=((Button)v).getText().toString();if(s.contains("Customer"))formCustomer(0);else if(s.contains("Product"))formProduct(0);else if(s.contains("Order"))formOrder(0);else if(s.contains("Purchase"))formPurchase(0);else if(s.contains("Payment"))formPayment(0);else if(s.contains("Invoice"))invoices();else reports();});}}
 String count(String t){Cursor c=db.q("SELECT COUNT(*) FROM "+t);c.moveToFirst();String s=c.getString(0);c.close();return s;}
 String sum(String t,String col){Cursor c=db.q("SELECT IFNULL(SUM("+col+"),0) FROM "+t);c.moveToFirst();String s=c.getString(0);c.close();return s;}
 String money(String t,String col){return "₹"+sum(t,col);}
 void section(String s){body.addView(tv(s,24));}
 void list(String table,String sql,String[] headers, RowClick click){LinearLayout l=box();Cursor c=db.q(sql);while(c.moveToNext()){StringBuilder s=new StringBuilder();for(int i=0;i<headers.length;i++){if(i>0)s.append(" • ");s.append(headers[i]).append(": ").append(c.getString(i));}TextView r=tv(s.toString(),15);r.setBackgroundColor(Color.WHITE);r.setOnClickListener(v->click.go(Integer.parseInt(c.getString(0))));l.addView(r);Button del=btn("Delete");del.setOnClickListener(v->{db.delete(table,"id=?",new String[]{c.getString(0)});page(title.getText().toString().split(" • ")[1]);});l.addView(del);}c.close();body.addView(l);}
 interface RowClick{void go(int id);}
 void customers(){Button a=btn("+ Add Customer");body.addView(a);a.setOnClickListener(v->formCustomer(0));list("customers","SELECT id,name,person,phone,address,city,state,pin,gstin FROM customers ORDER BY id DESC",new String[]{"ID","Shop","Person","Mobile","Address","City","State","PIN","GSTIN"},this::formCustomer);}
 void vendors(){Button a=btn("+ Add Vendor");body.addView(a);a.setOnClickListener(v->formVendor(0));list("vendors","SELECT id,name,person,phone,address,city,state,pin,gstin FROM vendors ORDER BY id DESC",new String[]{"ID","Vendor","Person","Mobile","Address","City","State","PIN","GSTIN"},this::formVendor);}
 void products(){Button a=btn("+ Add Product");body.addView(a);a.setOnClickListener(v->formProduct(0));list("products","SELECT id,sku,name,parent,category,b2b,gst,stock,mrp FROM products ORDER BY id DESC",new String[]{"ID","SKU","Product","Parent","Category","B2B","GST%","Stock","MRP"},this::formProduct);}
 EditText field(String name,String val,LinearLayout l){EditText e=ed(name);e.setText(val==null?"":val);l.addView(e);return e;}
 void formCustomer(int id){final Dialog d=new Dialog(this);LinearLayout l=box();l.addView(tv(id==0?"Add Customer":"Edit Customer",24));Cursor c=id==0?null:db.q("SELECT name,person,phone,address,city,state,pin,gstin,type FROM customers WHERE id=?",""+id);String[] v=new String[9];if(c!=null){c.moveToFirst();for(int i=0;i<9;i++)v[i]=c.getString(i);c.close();}String[] h={"Shop / Customer Name","Contact Person","Mobile","Full Address","City","State","PIN Code","GST Number","Type"};EditText[] e=new EditText[9];for(int i=0;i<9;i++)e[i]=field(h[i],v[i],l);Button s=btn("Save");l.addView(s);s.setOnClickListener(x->{ContentValues z=new ContentValues();for(int i=0;i<9;i++)z.put(new String[]{"name","person","phone","address","city","state","pin","gstin","type"}[i],e[i].getText().toString());if(id==0)db.getWritableDatabase().insert("customers",null,z);else db.update("customers",z,"id=?",""+id);d.dismiss();page("Customers");});d.setContentView(l);d.getWindow().setLayout(-1,-2);d.show();}
 void formVendor(int id){final Dialog d=new Dialog(this);LinearLayout l=box();l.addView(tv(id==0?"Add Vendor":"Edit Vendor",24));Cursor c=id==0?null:db.q("SELECT name,person,phone,address,city,state,pin,gstin FROM vendors WHERE id=?",""+id);String[] v=new String[8];if(c!=null){c.moveToFirst();for(int i=0;i<8;i++)v[i]=c.getString(i);c.close();}String[] h={"Vendor / Company","Contact Person","Mobile","Full Address","City","State","PIN Code","GST Number"};EditText[] e=new EditText[8];for(int i=0;i<8;i++)e[i]=field(h[i],v[i],l);Button s=btn("Save");l.addView(s);s.setOnClickListener(x->{ContentValues z=new ContentValues();String[] k={"name","person","phone","address","city","state","pin","gstin"};for(int i=0;i<8;i++)z.put(k[i],e[i].getText().toString());if(id==0)db.getWritableDatabase().insert("vendors",null,z);else db.update("vendors",z,"id=?",""+id);d.dismiss();page("Vendors");});d.setContentView(l);d.show();}
 void formProduct(int id){final Dialog d=new Dialog(this);LinearLayout l=box();l.addView(tv(id==0?"Add Product":"Edit Product",24));Cursor c=id==0?null:db.q("SELECT sku,name,parent,category,vendor_id,purchase,b2b,mrp,gst,stock,reorder,image FROM products WHERE id=?",""+id);String[] v=new String[12];if(c!=null){c.moveToFirst();for(int i=0;i<12;i++)v[i]=c.getString(i);c.close();}String[] h={"SKU","Product Name","Parent Category","Category","Vendor ID","Purchase Rate","B2B Sell Rate","MRP","GST % (5/12/18/custom)","Stock","Reorder Level","Image URI (optional)"};EditText[] e=new EditText[12];for(int i=0;i<12;i++)e[i]=field(h[i],v[i],l);Button img=btn("Choose Product Image");l.addView(img);img.setOnClickListener(x->{pendingImageField=e[11];Intent ii=new Intent(Intent.ACTION_OPEN_DOCUMENT);ii.setType("image/*");ii.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(ii,800);});Button s=btn("Save Product");l.addView(s);s.setOnClickListener(x->{ContentValues z=new ContentValues();String[] k={"sku","name","parent","category","vendor_id","purchase","b2b","mrp","gst","stock","reorder","image"};for(int i=0;i<12;i++){if(i==4){try{z.put(k[i],Integer.parseInt(e[i].getText().toString()));}catch(Exception q){z.put(k[i],0);}}else if(i>=5&&i<=10){try{z.put(k[i],Double.parseDouble(e[i].getText().toString()));}catch(Exception q){z.put(k[i],0);}}else z.put(k[i],e[i].getText().toString());}if(id==0)db.getWritableDatabase().insert("products",null,z);else db.update("products",z,"id=?",""+id);d.dismiss();page("Products");});d.setContentView(l);d.show();}
 String next(String prefix,String table,String col){Cursor c=db.q("SELECT COUNT(*) FROM "+table);c.moveToFirst();int n=c.getInt(0)+1;c.close();return prefix+String.format(Locale.US,"%05d",n);}
 void formOrder(int id){final Dialog d=new Dialog(this);LinearLayout l=box();l.addView(tv("Create B2B Order",24));Spinner cs=new Spinner(this);ArrayList<String> cn=new ArrayList<>();ArrayList<Integer> ci=new ArrayList<>();Cursor cc=db.q("SELECT id,name FROM customers ORDER BY name");while(cc.moveToNext()){ci.add(cc.getInt(0));cn.add(cc.getString(1));}cc.close();cs.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,cn));l.addView(cs);Spinner ps=new Spinner(this);ArrayList<String> pn=new ArrayList<>();ArrayList<Integer> pi=new ArrayList<>();Cursor pc=db.q("SELECT id,sku,name,stock FROM products WHERE stock>0 ORDER BY name");while(pc.moveToNext()){pi.add(pc.getInt(0));pn.add(pc.getString(1)+" • "+pc.getString(2)+" • Stock "+pc.getString(3));}pc.close();ps.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,pn));l.addView(ps);EditText qty=field("Quantity", "1",l), rate=field("Rate (B2B)","0",l), discount=field("Discount","0",l), transport=field("Transport","0",l), paid=field("Paid","0",l);TextView total=tv("Total: ₹0 | Due: ₹0",20);l.addView(total);Button calc=btn("Calculate");l.addView(calc);Button save=btn("Save Order");l.addView(save);Runnable r=()->{try{int p=pi.get(ps.getSelectedItemPosition());Cursor q=db.q("SELECT b2b,gst,stock FROM products WHERE id=?",""+p);q.moveToFirst();double rt=q.getDouble(0),gst=q.getDouble(1),st=q.getDouble(2);q.close();rate.setText(""+rt);double qt=Double.parseDouble(qty.getText().toString()),sub=qt*rt,di=Double.parseDouble(discount.getText().toString()),tr=Double.parseDouble(transport.getText().toString()),g=sub*gst/100,tot=sub-di+tr+g,pa=Double.parseDouble(paid.getText().toString());total.setText("Subtotal ₹"+sub+" | GST ₹"+g+" | Total ₹"+tot+" | Due ₹"+(tot-pa));}catch(Exception e){}};calc.setOnClickListener(v->r.run());save.setOnClickListener(v->{try{int cust=ci.get(cs.getSelectedItemPosition()),prod=pi.get(ps.getSelectedItemPosition());double qt=Double.parseDouble(qty.getText().toString()),rt=Double.parseDouble(rate.getText().toString()),di=Double.parseDouble(discount.getText().toString()),tr=Double.parseDouble(transport.getText().toString()),pa=Double.parseDouble(paid.getText().toString());Cursor q=db.q("SELECT gst,stock FROM products WHERE id=?",""+prod);q.moveToFirst();double gst=q.getDouble(0),stock=q.getDouble(1);q.close();if(qt>stock){Toast.makeText(this,"Only "+stock+" in stock",Toast.LENGTH_SHORT).show();return;}double sub=qt*rt,g=sub*gst/100,tot=sub-di+tr+g,due=tot-pa;String no=next("ORD-","orders","id");long oid=db.exec("INSERT INTO orders(orderno,customer_id,date,status,subtotal,discount,transport,gst,total,paid,due,payment_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",no,cust,df.format(new Date()),"Confirmed",sub,di,tr,g,tot,pa,due,due<=0?"Paid":pa>0?"Partial":"Pending");db.exec("INSERT INTO order_items(order_id,product_id,qty,rate,gst,amount) VALUES(?,?,?,?,?,?)",oid,prod,qt,rt,gst,sub);db.exec("INSERT INTO invoices(invno,order_id,date,status,total,paid,due) VALUES(?,?,?,?,?,?,?)",next("INV-","invoices","id"),oid,df.format(new Date()),due<=0?"Paid":"Due",tot,pa,due);db.exec("UPDATE products SET stock=stock-? WHERE id=?",qt,prod);d.dismiss();page("Orders");}catch(Exception e){Toast.makeText(this,"Check order fields",Toast.LENGTH_SHORT).show();}});d.setContentView(l);d.show();}
 void orders(){Button a=btn("+ Create Order");body.addView(a);a.setOnClickListener(v->formOrder(0));list("orders","SELECT o.id,o.orderno,c.name,o.date,o.total,o.paid,o.due,o.payment_status FROM orders o LEFT JOIN customers c ON c.id=o.customer_id ORDER BY o.id DESC",new String[]{"ID","Order","Customer","Date","Total","Paid","Due","Payment"},x->{});}
 void formPurchase(int id){final Dialog d=new Dialog(this);LinearLayout l=box();l.addView(tv("Purchase / Vendor Inward",24));Spinner vs=new Spinner(this);ArrayList<String> vn=new ArrayList<>();ArrayList<Integer> vi=new ArrayList<>();Cursor v=db.q("SELECT id,name FROM vendors ORDER BY name");while(v.moveToNext()){vi.add(v.getInt(0));vn.add(v.getString(1));}v.close();vs.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,vn));l.addView(vs);Spinner ps=new Spinner(this);ArrayList<String> pn=new ArrayList<>();ArrayList<Integer> pi=new ArrayList<>();Cursor p=db.q("SELECT id,sku,name FROM products ORDER BY name");while(p.moveToNext()){pi.add(p.getInt(0));pn.add(p.getString(1)+" • "+p.getString(2));}p.close();ps.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,pn));l.addView(ps);EditText qty=field("Quantity","1",l),rate=field("Purchase Rate","0",l),gst=field("GST %","5",l),transport=field("Transport","0",l),paid=field("Paid","0",l);Button s=btn("Save Purchase");l.addView(s);s.setOnClickListener(x->{try{int vi2=vi.get(vs.getSelectedItemPosition()),pi2=pi.get(ps.getSelectedItemPosition());double q=Double.parseDouble(qty.getText().toString()),r=Double.parseDouble(rate.getText().toString()),g=Double.parseDouble(gst.getText().toString()),tr=Double.parseDouble(transport.getText().toString()),pa=Double.parseDouble(paid.getText().toString()),sub=q*r,ga=sub*g/100,total=sub+ga+tr,due=total-pa;long idp=db.exec("INSERT INTO purchases(pono,vendor_id,date,status,subtotal,gst,transport,total,paid,due) VALUES(?,?,?,?,?,?,?,?,?,?)",next("PO-","purchases","id"),vi2,df.format(new Date()),"Received",sub,ga,tr,total,pa,due);db.exec("INSERT INTO purchase_items(purchase_id,product_id,qty,rate,gst,amount) VALUES(?,?,?,?,?,?)",idp,pi2,q,r,g,sub);db.exec("UPDATE products SET stock=stock+?,purchase=? WHERE id=?",q,r,pi2);d.dismiss();page("Purchases");}catch(Exception e){Toast.makeText(this,"Check purchase fields",Toast.LENGTH_SHORT).show();}});d.setContentView(l);d.show();}
 void purchases(){Button a=btn("+ Add Purchase / Inward");body.addView(a);a.setOnClickListener(v->formPurchase(0));list("purchases","SELECT p.id,p.pono,v.name,p.date,p.subtotal,p.gst,p.transport,p.total,p.paid,p.due FROM purchases p LEFT JOIN vendors v ON v.id=p.vendor_id ORDER BY p.id DESC",new String[]{"ID","PO","Vendor","Date","Subtotal","GST","Transport","Total","Paid","Due"},x->{});}
 void invoices(){Button a=btn("Invoice PDFs are generated from orders");body.addView(a);list("invoices","SELECT id,invno,date,status,total,paid,due FROM invoices ORDER BY id DESC",new String[]{"ID","Invoice","Date","Status","Total","Paid","Due"},this::invoiceActions);}
 void invoiceActions(int id){Cursor c=db.q("SELECT invno,order_id,date,status,total,paid,due FROM invoices WHERE id=?",""+id);if(!c.moveToFirst()){c.close();return;}String inv=c.getString(0);int oid=c.getInt(1);c.close();new AlertDialog.Builder(this).setTitle(inv).setItems(new String[]{"Preview / Save PDF","Delete Invoice"},(d,w)->{if(w==0)makeInvoicePdf(id);else{db.delete("invoices","id=?",""+id);page("Invoices");}}).show();}
 void makeInvoicePdf(int iid){Cursor c=db.q("SELECT i.invno,i.order_id,i.date,i.status,i.total,i.paid,i.due,o.customer_id FROM invoices i JOIN orders o ON o.id=i.order_id WHERE i.id=?",""+iid);if(!c.moveToFirst()){c.close();return;}String inv=c.getString(0),date=c.getString(2);int cid=c.getInt(7);double total=c.getDouble(4),paid=c.getDouble(5),due=c.getDouble(6);c.close();Cursor cu=db.q("SELECT name,person,phone,address,city,state,pin,gstin FROM customers WHERE id=?",""+cid);String cust="",addr="",gstin="";if(cu.moveToFirst()){cust=cu.getString(0)+" / "+cu.getString(1);addr=cu.getString(3)+", "+cu.getString(4)+", "+cu.getString(5)+" - "+cu.getString(6);gstin=cu.getString(7);}cu.close();PdfDocument pdf=new PdfDocument();PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas x=page.getCanvas();Paint p=new Paint();p.setTextSize(22);p.setColor(dark);x.drawText(db.get("brand"),40,55,p);p.setTextSize(13);x.drawText("TAX INVOICE",420,55,p);p.setTextSize(12);x.drawText("Invoice: "+inv,40,85,p);x.drawText("Date: "+date,40,105,p);x.drawText("Bill To: "+cust,40,145,p);x.drawText(addr,40,165,p);x.drawText("GSTIN: "+gstin,40,185,p);int y=230;x.drawText("Product / Qty / Rate / GST / Amount",40,y,p);y+=25;Cursor it=db.q("SELECT p.name,oi.qty,oi.rate,oi.gst,oi.amount FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?",""+getOrderId(iid));while(it.moveToNext()){x.drawText(it.getString(0)+" / "+it.getString(1)+" / ₹"+it.getString(2)+" / "+it.getString(3)+"% / ₹"+it.getString(4),40,y,p);y+=22;}it.close();y+=30;x.drawText("Total: ₹"+total,360,y,p);x.drawText("Paid: ₹"+paid,360,y+25,p);x.drawText("Balance Due: ₹"+due,360,y+50,p);pdf.finishPage(page);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,inv+".pdf");startActivityForResult(i,700);pendingPdf=pdf;}
 PdfDocument pendingPdf;EditText pendingImageField;int getOrderId(int iid){Cursor c=db.q("SELECT order_id FROM invoices WHERE id=?",""+iid);int x=0;if(c.moveToFirst())x=c.getInt(0);c.close();return x;}
 @Override protected void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(r==700&&code==RESULT_OK&&data!=null&&pendingPdf!=null){try{OutputStream o=getContentResolver().openOutputStream(data.getData());pendingPdf.writeTo(o);o.close();pendingPdf.close();Toast.makeText(this,"Invoice PDF saved",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"PDF save failed",Toast.LENGTH_SHORT).show();}} else if(r==701&&code==RESULT_OK&&data!=null&&pendingPdf!=null){try{OutputStream o=getContentResolver().openOutputStream(data.getData());pendingPdf.writeTo(o);o.close();pendingPdf.close();Toast.makeText(this,"Catalogue PDF saved",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Catalogue save failed",Toast.LENGTH_SHORT).show();}} else if(r==703&&code==RESULT_OK&&data!=null&&pendingText!=null){try{OutputStream o=getContentResolver().openOutputStream(data.getData());o.write(pendingText.getBytes("UTF-8"));o.close();Toast.makeText(this,"Backup saved",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(this,"Backup failed",Toast.LENGTH_SHORT).show();}} else if(r==702&&code==RESULT_OK&&data!=null){restoreJson(data.getData());} else if(r==800&&code==RESULT_OK&&data!=null&&pendingImageField!=null){pendingImageField.setText(data.getData().toString());Toast.makeText(this,"Product image selected",Toast.LENGTH_SHORT).show();}}
 void formPayment(int id){final Dialog d=new Dialog(this);LinearLayout l=box();l.addView(tv("Record Payment",24));Spinner os=new Spinner(this);ArrayList<String> on=new ArrayList<>();ArrayList<Integer> oi=new ArrayList<>();Cursor o=db.q("SELECT id,orderno,due FROM orders WHERE due>0 ORDER BY id DESC");while(o.moveToNext()){oi.add(o.getInt(0));on.add(o.getString(1)+" • Due ₹"+o.getString(2));}o.close();os.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,on));l.addView(os);EditText am=field("Amount","0",l);Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"UPI","Cash","Bank Transfer","Card","Cheque"}));l.addView(mode);EditText note=field("Note","",l);Button s=btn("Save Payment");l.addView(s);s.setOnClickListener(v->{try{int oid=oi.get(os.getSelectedItemPosition());double a=Double.parseDouble(am.getText().toString());Cursor q=db.q("SELECT customer_id,total,paid FROM orders WHERE id=?",""+oid);q.moveToFirst();int cid=q.getInt(0);double total=q.getDouble(1),paid=q.getDouble(2)+a;double due=Math.max(0,total-paid);q.close();db.exec("INSERT INTO payments(receipt,date,order_id,customer_id,amount,mode,note) VALUES(?,?,?,?,?,?,?)",next("REC-","payments","id"),df.format(new Date()),oid,cid,a,mode.getSelectedItem().toString(),note.getText().toString());db.exec("UPDATE orders SET paid=?,due=?,payment_status=? WHERE id=?",paid,due,due<=0?"Paid":"Partial",oid);db.exec("UPDATE invoices SET paid=?,due=?,status=? WHERE order_id=?",paid,due,due<=0?"Paid":"Due",oid);d.dismiss();page("Payments");}catch(Exception e){Toast.makeText(this,"Check payment",Toast.LENGTH_SHORT).show();}});d.setContentView(l);d.show();}
 void payments(){Button a=btn("+ Record Payment");body.addView(a);a.setOnClickListener(v->formPayment(0));list("payments","SELECT p.id,p.receipt,p.date,c.name,p.amount,p.mode,p.note FROM payments p LEFT JOIN customers c ON c.id=p.customer_id ORDER BY p.id DESC",new String[]{"ID","Receipt","Date","Customer","Amount","Mode","Note"},x->{});}
 void stock(){section("Stock Control");list("products","SELECT id,sku,name,stock,reorder,b2b,mrp FROM products ORDER BY stock ASC",new String[]{"ID","SKU","Product","Stock","Reorder","B2B","MRP"},this::formProduct);}
 void reports(){section("Business Reports");body.addView(tv("Sales Total: "+money("orders","total"),20));body.addView(tv("Collection: "+money("orders","paid"),20));body.addView(tv("Outstanding: "+money("orders","due"),20));body.addView(tv("Purchase Value: "+money("purchases","total"),20));body.addView(tv("Payments Received: "+money("payments","amount"),20));body.addView(tv("Stock Units: "+sum("products","stock"),20));body.addView(tv("Low Stock: "+lowStock(),20));body.addView(tv("Estimated Gross Margin: ₹"+grossMargin(),20));}
 String lowStock(){Cursor c=db.q("SELECT COUNT(*) FROM products WHERE stock<=reorder");c.moveToFirst();String x=c.getString(0);c.close();return x;}
 String grossMargin(){Cursor c=db.q("SELECT IFNULL(SUM(oi.qty*(oi.rate-p.purchase)),0) FROM order_items oi JOIN products p ON p.id=oi.product_id");c.moveToFirst();String x=c.getString(0);c.close();return x;}
 void catalogue(){section("Customer Catalogue");body.addView(tv("Product images, SKU, category, GST and B2B price can be shared as a PDF.",15));Button b=btn("Generate Catalogue PDF");body.addView(b);b.setOnClickListener(v->makeCatalogue());list("products","SELECT id,sku,name,parent,category,b2b,gst,stock FROM products ORDER BY parent,category,name",new String[]{"ID","SKU","Product","Parent","Category","B2B","GST","Stock"},this::formProduct);}
 void makeCatalogue(){PdfDocument pdf=new PdfDocument();PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas x=page.getCanvas();Paint p=new Paint();p.setColor(dark);p.setTextSize(24);x.drawText(db.get("brand"),40,55,p);p.setTextSize(13);x.drawText("Customer Catalogue • "+df.format(new Date()),40,82,p);int y=120;Cursor c=db.q("SELECT sku,name,parent,category,b2b,gst,stock FROM products ORDER BY name");while(c.moveToNext()){if(y>790){pdf.finishPage(page);page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,pdf.getPages().size()+1).create());x=page.getCanvas();y=50;}x.drawText(c.getString(0)+" • "+c.getString(1),40,y,p);x.drawText(c.getString(2)+" / "+c.getString(3)+" • ₹"+c.getString(4)+" • GST "+c.getString(5)+"% • Stock "+c.getString(6),40,y+18,p);y+=42;}c.close();pdf.finishPage(page);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/pdf");i.putExtra(Intent.EXTRA_TITLE,"Gezeno_Customer_Catalogue.pdf");startActivityForResult(i,701);pendingPdf=pdf;}
 void settings(){section("Brand & Business Settings");String[] k={"brand","subtitle","phone","email","address","gstin","taxmode","username","password"};String[] h={"Brand Name","Subtitle","Phone","Email","Business Address","Business GSTIN","Tax Mode (CGST+SGST/IGST)","Login Username","Login Password"};EditText[] e=new EditText[k.length];for(int i=0;i<k.length;i++)e[i]=field(h[i],db.get(k[i]),body);Button save=btn("Save Settings");body.addView(save);save.setOnClickListener(v->{for(int i=0;i<k.length;i++)db.put(k[i],e[i].getText().toString());Toast.makeText(this,"Settings saved",Toast.LENGTH_SHORT).show();showApp();});Button backup=btn("Backup Database (JSON)");body.addView(backup);backup.setOnClickListener(v->backup());Button restore=btn("Restore Database (JSON)");body.addView(restore);restore.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/json");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,702);});Button logout=btn("Logout");body.addView(logout);logout.setOnClickListener(v->showLogin());}
 void backup(){try{org.json.JSONObject all=new org.json.JSONObject();String[] ts={"customers","vendors","products","orders","order_items","invoices","payments","purchases","purchase_items","settings"};for(String t:ts){Cursor c=db.q("SELECT * FROM "+t);org.json.JSONArray a=new org.json.JSONArray();String[] cols=c.getColumnNames();while(c.moveToNext()){org.json.JSONObject o=new org.json.JSONObject();for(int i=0;i<cols.length;i++)o.put(cols[i],c.getString(i));a.put(o);}c.close();all.put(t,a);}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"Gezeno_Backup.json");pendingText=all.toString();startActivityForResult(i,703);}catch(Exception e){Toast.makeText(this,"Backup failed",Toast.LENGTH_SHORT).show();}}
 String pendingText; @Override protected void onResume(){super.onResume();}
 void restoreJson(Uri uri){try{InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)b.write(buf,0,n);in.close();org.json.JSONObject all=new org.json.JSONObject(new String(b.toByteArray(),"UTF-8"));String[] ts={"settings","customers","vendors","products","orders","order_items","invoices","payments","purchases","purchase_items"};db.getWritableDatabase().beginTransaction();try{for(String t:ts)db.delete(t,null);for(String t:ts){org.json.JSONArray a=all.optJSONArray(t);if(a==null)continue;for(int j=0;j<a.length();j++){org.json.JSONObject o=a.getJSONObject(j);ContentValues cv=new ContentValues();java.util.Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next();Object v=o.get(k);if(v==org.json.JSONObject.NULL)cv.putNull(k);else cv.put(k,v.toString());}db.getWritableDatabase().insert(t,null,cv);}}db.getWritableDatabase().setTransactionSuccessful();}finally{db.getWritableDatabase().endTransaction();}Toast.makeText(this,"Backup restored successfully",Toast.LENGTH_LONG).show();showApp();}catch(Exception e){Toast.makeText(this,"Restore failed: "+e.getMessage(),Toast.LENGTH_LONG).show();}}

}
